import type { Color, PieceType } from '@/types/remorse';
import type { PieceIcon } from './icons';

// SVGs are generated by scripts/remorse-pieces.mjs; ids must match its SETS
export const PIECE_SETS = [
  { id: 'mourners', name: 'Mourners', blurb: 'Hooded, grieving figures' },
  { id: 'chunky', name: 'Chunky', blurb: 'Short, wide and rounded' },
  { id: 'staunton', name: 'Stout Staunton', blurb: 'Classic turned wood' },
  { id: 'monuments', name: 'Monuments', blurb: 'Tiny stone monuments' },
  { id: 'pebble', name: 'Pebble', blurb: 'Smooth, one-piece shapes' },
] as const;

export type PieceSetId = (typeof PIECE_SETS)[number]['id'];

export const DEFAULT_PIECE_SET: PieceSetId = 'mourners';

export const isPieceSet = (id: unknown): id is PieceSetId =>
  PIECE_SETS.some((set) => set.id === id);

export const BOARD_SRC = '/images/remorse/board.svg';

export const pieceSrc = (set: PieceSetId, color: Color, type: PieceType) =>
  `/images/remorse/pieces/${set}/${color}${type}.svg`;

// piece icons are named like the images (color + type)
export const pieceIconSrc = (set: PieceSetId, icon: PieceIcon) =>
  `/images/remorse/pieces/${set}/${icon}.svg`;
